<script setup>
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {readWorks,readDrafts,workTypes,removeWork,restoreWork,exportWorks,importWorks,maxWorks,updateWork,compareWorks,comparisonLabel,comparisonValue} from '../../room/workshelf.js';
import {downloadJson} from '../../room/storage.js';
const router=useRouter(),route=useRoute(),works=ref([]),drafts=ref([]),filter=ref('all'),query=ref(''),order=ref('new'),message=ref(''),removed=ref(null),fileInput=ref(null),busy=ref(false),editing=ref(''),editTitle=ref(''),editTags=ref(''),selected=ref([]);
let alive=true;
function refresh(){works.value=readWorks();drafts.value=readDrafts();selected.value=selected.value.filter(id=>works.value.some(w=>w.id===id));}
refresh();try{exportWorks();}catch(e){message.value=e.message;}
const visible=computed(()=>works.value.filter(w=>(filter.value==='all'||w.kind===filter.value)&&(w.title+' '+(w.tags||[]).join(' ')).toLowerCase().includes(query.value.trim().toLowerCase())).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||(order.value==='old'?a.at-b.at:order.value==='title'?a.title.localeCompare(b.title,'zh-CN'):b.at-a.at)));
const kinds=computed(()=>[...new Set(works.value.map(w=>w.kind))]);
const compared=computed(()=>selected.value.map(id=>works.value.find(w=>w.id===id)).filter(Boolean));
const differences=computed(()=>compared.value.length===2&&compared.value[0].kind===compared.value[1].kind?compareWorks(...compared.value):[]);
const formatDate=at=>new Date(at).toLocaleString('zh-CN',{month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'});
async function open(work){try{await router.push(restoreWork(work.id));}catch(e){message.value=e.message;}}
function remove(work){try{removed.value=removeWork(work.id);message.value='已移出作品架，编辑页草稿保留，可以撤销。';refresh();}catch(e){message.value=e.message;}}
function undo(){try{importWorks(JSON.stringify({version:1,works:[removed.value]}));removed.value=null;message.value='作品已放回原位。';refresh();}catch(e){message.value=e.message;}}
function backup(){try{downloadJson(exportWorks(),'hitori-workshelf-backup.json');message.value='已导出作品、预览和编辑数据，可在另一台设备导入。';}catch(e){message.value=e.message;}}
async function importFile(event){const file=event.target.files?.[0];if(!file||busy.value)return;busy.value=true;try{if(file.size>5*1024*1024)throw new Error('备份不能超过5MiB。');const text=await file.text();if(!alive)return;const count=importWorks(text);message.value=`已合并 ${count} 个新版本，原作品和草稿都保留。`;refresh();}catch(e){if(alive)message.value=e.message;}finally{if(alive){busy.value=false;event.target.value='';}}}
function edit(w){editing.value=w.id;editTitle.value=w.title;editTags.value=(w.tags||[]).join('，');}
function saveMeta(w){try{updateWork(w.id,{title:editTitle.value,tags:editTags.value.split(/[,，]/).map(t=>t.trim()).filter(Boolean)});editing.value='';message.value='作品名称和标签已保存，画面与原版本时间保留。';refresh();}catch(e){message.value=e.message;}}
function pin(w){try{updateWork(w.id,{pinned:!w.pinned});refresh();}catch(e){message.value=e.message;}}
function choose(w){if(selected.value.includes(w.id)){selected.value=selected.value.filter(id=>id!==w.id);return;}if(selected.value.length>=2){message.value='每次选择两个版本对比，先取消一个。';return;}if(compared.value[0]&&compared.value[0].kind!==w.kind){message.value='请选择同一类型的两个版本。';return;}selected.value.push(w.id);}
onMounted(()=>{window.addEventListener('storage',refresh);window.addEventListener('hitori:works-changed',refresh);if(route.query.work)document.querySelector(`[data-work-id="${CSS.escape(String(route.query.work))}"]`)?.scrollIntoView({block:'center'});});
onBeforeUnmount(()=>{alive=false;window.removeEventListener('storage',refresh);window.removeEventListener('hitori:works-changed',refresh);});
</script>
<template><section class="workshelf" aria-labelledby="works-title"><div class="discovery-section-heading"><div><p class="room-kicker">我的小小收藏展</p><h2 id="works-title">那些由你完成的瞬间</h2></div><span class="works-count">{{works.length}} / {{maxWorks}} 个版本</span></div><p class="works-intro">给作品取名字、贴标签，把最喜欢的置顶。继续编辑时，当前不同的草稿会先另存一份。</p><div class="room-actions"><button type="button" @click="backup">导出作品架备份 ↓</button><button type="button" :disabled="busy" @click="fileInput.click()">{{busy?'读取中…':'导入作品架备份'}}</button><input ref="fileInput" type="file" accept=".json,application/json" hidden aria-label="选择作品架备份" @change="importFile"><button v-if="removed" type="button" @click="undo">撤销移出</button></div><p class="room-status" role="status">{{message}}</p>
 <div v-if="works.length" class="rich-toolbar"><label class="room-field">查找作品<input v-model="query" type="search" placeholder="搜索作品名称或标签" maxlength="100"></label><label class="room-field">排序<select v-model="order"><option value="new">新版本优先</option><option value="old">旧版本优先</option><option value="title">按作品名称</option></select></label></div>
 <div v-if="works.length" class="activity-filters" aria-label="筛选作品"><button type="button" :aria-pressed="filter==='all'" @click="filter='all'">全部作品</button><button v-for="kind in kinds" :key="kind" type="button" :aria-pressed="filter===kind" @click="filter=kind">{{workTypes[kind].label}}</button></div>
 <section v-if="selected.length" class="work-compare-panel" aria-labelledby="compare-title"><div class="room-actions"><h3 id="compare-title">版本对比 · {{selected.length}} / 2</h3><button type="button" @click="selected=[]">清空对比选择</button></div><p v-if="selected.length===1">再选择一个同类型版本，可以并排看预览与修改。</p><template v-else><div class="compare-grid"><div v-for="w in compared" :key="w.id"><h4>{{w.title}}</h4><p>{{formatDate(w.at)}}</p><img v-if="w.preview" :src="w.preview" :alt="w.title"><p v-else>这个版本保存了编辑数据，没有画面预览。</p></div></div><p>{{differences.length?`发现${differences.length}${differences.length===40?'处以上':'处'}修改`:'两个版本的编辑数据相同。'}}</p><div v-if="differences.length" class="compare-table-wrap"><table><thead><tr><th>修改位置</th><th>左侧版本</th><th>右侧版本</th></tr></thead><tbody><tr v-for="(d,i) in differences" :key="i"><th>{{comparisonLabel(d.path)}}</th><td>{{comparisonValue(d.before)}}</td><td>{{comparisonValue(d.after)}}</td></tr></tbody></table></div></template></section>
 <div v-if="visible.length" class="works-grid"><article v-for="work in visible" :key="work.id" class="work-card" :class="{'is-pinned':work.pinned}" :data-work-id="work.id"><div class="work-preview"><img v-if="work.preview" :src="work.preview" :alt="`${work.title}的保存预览`" width="360" height="300" loading="lazy"><div v-else class="work-sound-preview"><span>{{workTypes[work.kind].icon}}</span><small>{{workTypes[work.kind].label}}</small><strong>{{work.title}}</strong></div></div><div class="work-copy"><p>{{work.pinned?'★ 置顶 · ':''}}{{workTypes[work.kind].label}} · <time :datetime="new Date(work.at).toISOString()">{{formatDate(work.at)}}</time></p><h3>{{work.title}}</h3><p v-if="work.tags.length" class="work-tags">{{work.tags.map(t=>'#'+t).join(' ')}}</p><div class="work-card-actions"><button type="button" class="primary" @click="open(work)">继续编辑 →</button><button type="button" @click="edit(work)">整理</button><button type="button" @click="pin(work)">{{work.pinned?'取消置顶':'置顶'}}</button><button type="button" @click="downloadJson({version:1,works:[work]},'hitori-work.json')">备份此版本</button><a v-if="work.preview" :href="work.preview" :download="`hitori-work-${work.id}.webp`">保存预览 ↓</a><button type="button" class="work-remove" @click="remove(work)">移出作品架</button></div><label class="room-check"><input type="checkbox" :checked="selected.includes(work.id)" @change="choose(work)">对比此版本</label><div v-if="editing===work.id" class="work-metadata"><label class="room-field">作品名称<input v-model="editTitle" maxlength="90"></label><label class="room-field">标签（逗号分隔，最多8个）<input v-model="editTags" maxlength="200"></label><div class="work-card-actions"><button type="button" @click="saveMeta(work)">保存整理</button><button type="button" @click="editing=''">取消</button></div></div></div></article></div>
 <div v-else-if="!works.length" class="works-empty"><span>▣</span><h3>第一件作品，留一个位置给你。</h3><p>去拍张合影或画一页漫画，再点击编辑页上方的“存入作品架”。</p><div><RouterLink to="/room/photobooth">拍一张合影 ↗</RouterLink><RouterLink to="/room/comic">写一页漫画 ↗</RouterLink></div></div><p v-else class="room-hint">没有符合条件的作品，试试别的名称、标签或分类。</p>
 <section v-if="drafts.length" class="works-drafts"><div class="discovery-section-heading"><div><p class="room-kicker">草稿也在这里</p><h2>还没收进架子的灵感</h2></div></div><div class="activity-cards"><RouterLink v-for="draft in drafts" :key="draft.kind" :to="`/room/${draft.kind}`" class="activity-card"><span class="activity-icon">{{workTypes[draft.kind].icon}}</span><div><h3>{{workTypes[draft.kind].label}}</h3><p>{{draft.title}}</p></div><span>↗</span></RouterLink></div></section><p class="room-hint works-storage-note">作品保存在当前浏览器，清除网站数据会移除本机记录。导出备份可在另一台设备继续；导入合并作品，不替换草稿。</p></section></template>
<style scoped>
.works-intro{font-size:13px;color:#cbb9ca;line-height:1.9;max-width:720px}.works-count{color:#ba9eaf;font-size:12px}.works-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-top:22px}.work-card{background:#fff8ed;color:#493b47;border:1px solid #cdb6a7;min-width:0}.work-preview{height:240px;background:#e8d5db;overflow:hidden}.work-preview>img{width:100%;height:100%;object-fit:contain;display:block;padding:12px}.work-sound-preview{height:100%;padding:28px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;background:repeating-linear-gradient(0deg,transparent,transparent 23px,#bfa7b633 24px)}.work-sound-preview>span{font-size:50px;color:#93657e}.work-sound-preview small{font-size:10px}.work-sound-preview strong{text-align:center;font-size:17px;line-height:1.7}.work-copy{padding:20px}.work-copy>p{font-size:10px;color:#8a6e79;margin:0 0 10px}.work-copy h3{font-size:18px;line-height:1.7;margin:0 0 18px;overflow-wrap:anywhere}.work-card-actions{display:flex;flex-wrap:wrap;gap:8px}.work-card-actions button{font-size:11px;padding:8px 10px}.work-card-actions a{color:#79596f;font-size:11px;min-height:44px;display:inline-flex;align-items:center}.work-card-actions .work-remove{background:transparent;border:0;text-decoration:underline;color:#8a6e79;padding:8px 0;margin-left:auto}.works-empty{padding:45px 24px;border:1px dashed #816577;background:#231c2a;text-align:center}.works-empty>span{font-size:54px;color:#d6a0bb}.works-empty h3{font-size:23px;line-height:1.7}.works-empty p{font-size:13px;color:#c6acbd;line-height:1.9}.works-empty>div{display:flex;flex-wrap:wrap;justify-content:center;gap:20px}.works-empty a{display:inline-flex;align-items:center;min-height:44px;color:#edc4d7;font-size:13px}.works-drafts{margin-top:40px}.works-drafts .activity-icon{background:#d9b3ca}.works-storage-note{margin-top:26px}@media(max-width:950px){.works-grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.works-grid{grid-template-columns:1fr}.work-preview{height:270px}.works-empty{padding:28px 16px}.work-card-actions .work-remove{margin-left:0}}
</style>
